import { Configuration, OpenAIApi } from 'openai';

const enhanceParticipantPhoto = async (base64Image: string): Promise<string> => {
  // Check that OPENAI_API_KEY is set
  if (!process.env.OPENAI_API_KEY) {
    throw new Error('OPENAI_API_KEY is not set.');
  }

  const configuration = new Configuration({
    apiKey: process.env.OPENAI_API_KEY,
  });

  const openai = new OpenAIApi(configuration);

  // Generate a unique identifier for the image
  const imageId = `${Date.now()}`;

  const response = await openai.createImage({
    prompt: "Make a high-quality, professional-looking profile picture.",
    n: 1,
    size: "256x256",
    response_format: "b64_json",
  });

  const enhancedImage = response.data.data[0].b64_json;
  return `data:image/png;base64,${enhancedImage}`;
};

export { enhanceParticipantPhoto };
```


