import { GoogleGenAI, Type, Modality } from "@google/genai";
import { Participant, PRDraftReview } from '../types';

if (!process.env.API_KEY) {
  console.warn("API_KEY environment variable not set. Using a mock response.");
}

/**
 * Generates a PR Draft using a structured Role-Goal-Input-Output-Tone framework.
 */
const generatePRDraft = async (participant: Omit<Participant, 'id' | 'prDraft' | 'photo' | 'status' | 'prDraftReview' | 'qrCode'>): Promise<string> => {
  if (!process.env.API_KEY) {
    return Promise.resolve(`This is a mock PR draft for ${participant.name}, a promising ${participant.targetAudience} from ${participant.collegeName}, studying ${participant.course}. Enrolled in the "${participant.programEnrolled}" program, ${participant.name} is passionate about agriculture and food processing. With goals like "${participant.goals}" and hobbies such as "${participant.hobbies}", they are poised to make a significant impact. This training will further equip them with practical skills to excel in the agro-economic sector, contributing to innovative startups and community growth. We look forward to their success.`);
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    const prompt = `
      Role: Act as a Senior Public Relations Manager and Career Development Mentor for 'GWellth', a premier skill training institute specializing in Food Processing and Agriculture.

      Goal: Write a compelling, professional 100-word profile (PR Draft) for a new trainee joining our program. The draft should bridge their current background with their future potential in the industry, specifically referencing the program they are enrolled in.

      Input:
      - Name: ${participant.name}
      - Background Category: ${participant.targetAudience}
      - Education: ${participant.course} at ${participant.collegeName}
      - Enrolled Program: ${participant.programEnrolled}
      - Location: ${participant.city}
      - Hobbies/Interests: ${participant.hobbies}
      - Professional Goals: ${participant.goals}

      Output:
      A single, coherent paragraph (~100 words). The output must be plain text (no markdown, bolding, or headers). It should read like a professional biography suitable for a LinkedIn summary or a press release intro.

      Tone: Professional, Inspiring, Empowering, and Corporate-Ready. It should sound optimistic about their future contribution to the agro-economic sector.
    `;

    const response = await ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
    });

    return response.text || "";
  } catch (error) {
    console.error("Error generating PR draft with Gemini:", error);
    throw new Error("Failed to generate PR draft. Please try again.");
  }
};

const reviewPRDraft = async (draft: string): Promise<PRDraftReview> => {
  if (!process.env.API_KEY) {
    return Promise.resolve({
      score: 8,
      feedback: [
        "Excellent positive tone and professional language.",
        "Clearly highlights the participant's potential.",
        "Could be slightly more concise to improve impact."
      ]
    });
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: `As a Public Relations expert, please review the following PR draft and provide a score out of 10 and 2-3 brief feedback points. Draft: "${draft}"`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            score: {
              type: Type.INTEGER,
              description: 'A quality score for the PR draft, from 1 to 10.'
            },
            feedback: {
              type: Type.ARRAY,
              description: 'An array of 2-3 brief, constructive feedback points.',
              items: {
                type: Type.STRING
              }
            }
          }
        }
      }
    });

    const jsonResponse = JSON.parse(response.text || "{}");
    return jsonResponse as PRDraftReview;

  } catch (error) {
    console.error("Error reviewing PR draft with Gemini:", error);
    return {
      score: 0,
      feedback: ["Failed to get PR draft review. Please check the content manually."]
    };
  }
};

const enhanceParticipantPhoto = async (base64Image: string): Promise<string> => {
  if (!process.env.API_KEY) return base64Image;

  const parts = base64Image.match(/^data:(image\/\w+);base64,(.*)$/);
  if (!parts || parts.length !== 3) return base64Image;
  const mimeType = parts[1];
  const data = parts[2];

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: {
        parts: [
          { inlineData: { data, mimeType } },
          { text: "Enhance this person's photo for a professional profile. Give it a clean, professional-looking, and neutral background suitable for a corporate or program ID. Do not change the person's facial features or appearance. Just improve the lighting and replace the background." },
        ],
      },
      config: {
        responseModalities: [Modality.IMAGE],
      },
    });

    const imagePart = response.candidates?.[0]?.content?.parts?.find(part => 'inlineData' in part);
    if (imagePart && imagePart.inlineData) {
      const responseMimeType = imagePart.inlineData.mimeType || 'image/png';
      return `data:${responseMimeType};base64,${imagePart.inlineData.data}`;
    }
    return base64Image;
  } catch (error) {
    console.error("Error enhancing photo with Gemini:", error);
    return base64Image;
  }
};

export interface CollegeSearchResult {
  name: string;
  url: string;
}

/**
 * Searches for colleges using Gemini's Google Maps tool.
 */
const searchColleges = async (query: string): Promise<CollegeSearchResult[]> => {
  if (!process.env.API_KEY) {
    return [
      { name: "Sample Agricultural Institute", url: "https://maps.google.com" },
      { name: "Global Food Tech University", url: "https://maps.google.com" }
    ];
  }

  try {
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    let lat: number | undefined;
    let lng: number | undefined;

    try {
        const position = await new Promise<GeolocationPosition>((resolve, reject) => {
            navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 3000 });
        });
        lat = position.coords.latitude;
        lng = position.coords.longitude;
    } catch (e) {
        console.warn("Geolocation skipped for college search.");
    }

    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-lite-latest",
      contents: `Find colleges or educational institutes matching: "${query}"`,
      config: {
        tools: [{ googleMaps: {} }],
        ...(lat && lng ? {
          toolConfig: {
            retrievalConfig: {
              latLng: { latitude: lat, longitude: lng }
            }
          }
        } : {})
      },
    });

    const results: CollegeSearchResult[] = [];
    const chunks = response.candidates?.[0]?.groundingMetadata?.groundingChunks || [];

    for (const chunk of chunks) {
      if (chunk.maps) {
        results.push({
          name: chunk.maps.title || "Unknown Institution",
          url: chunk.maps.uri || "",
        });
      }
    }

    return results;
  } catch (error) {
    console.error("Error searching colleges with Gemini Maps:", error);
    return [];
  }
};


